<script setup lang="ts">
import { uiText } from '@/i18n'

import {onMounted,onBeforeUnmount,ref} from 'vue'
import {request} from '@/api/client'
const emit=defineEmits<{refresh:[]}>(), items=ref<{id:string;groupId:number;groupName:string;role:string}[]>([]),groupId=ref(''),busy=ref(false),error=ref(''),message=ref('');let active=true
onBeforeUnmount(()=>{active=false})
type InvitationHistory={id:string;groupName:string;displayName:string;identityCode:string;kind:string;status:string;expiresAt:string}
const history=ref<InvitationHistory[]>([]),page=ref(0),hasNext=ref(false)
const statusText=(status:string)=>uiText(({PENDING:'待处理',ACCEPTED:'已接受',REJECTED:'已拒绝',CANCELLED:'已撤回',EXPIRED:'已过期'} as Record<string,string>)[status]||status)
async function loadHistory(){try{const r=await request<{items:InvitationHistory[];hasNext:boolean}>('/workspaces/invitations/history?page='+page.value);if(active){history.value=r.items;hasNext.value=r.hasNext}}catch(e){if(active)error.value=(e as Error).message}}
async function historyPage(next:number){if(busy.value)return;page.value=next;busy.value=true;await loadHistory();if(active)busy.value=false}
onMounted(loadHistory)
async function load(){try{const r=await request<typeof items.value>('/workspaces/invitations');if(active)items.value=r}catch(e){if(active)error.value=(e as Error).message}}
onMounted(load)
async function run(path:string,body:unknown){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await request(path,{method:'POST',body:JSON.stringify(body)});if(active){await Promise.all([load(),loadHistory()]);emit('refresh');message.value='操作已完成'}}catch(e){if(active)error.value=(e as Error).message}finally{if(active)busy.value=false}}
</script>
<template><details class="invitation-panel"><summary>{{ uiText('邀请与加入申请') }} <span v-if="items.length">· {{items.length}} {{ uiText('个待确认') }}</span></summary><p v-if="error" class="form-error" role="alert">{{ uiText(error) }}</p><p v-if="message" role="status">{{uiText(message)}}</p><div v-for="i in items" :key="i.id" class="invite-row"><strong>{{i.groupName}}</strong><span>{{i.role==='VIEWER'?uiText('访客'):uiText('成员')}}</span><button class="table-action" :disabled="busy" @click="run('/workspaces/invitations/'+i.id+'/decision',{accept:true})">{{ uiText('接受') }}</button><button class="table-action" :disabled="busy" @click="run('/workspaces/invitations/'+i.id+'/decision',{accept:false})">{{ uiText('拒绝') }}</button></div><form @submit.prevent="run('/workspaces/'+Number(groupId)+'/join-request',{})"><label>{{ uiText('群组编号') }}<input v-model="groupId" class="field-input" type="number" min="1" required :placeholder="uiText('向群主索取编号')" /></label><button class="button button--ghost" :disabled="busy||!groupId">{{ uiText('申请加入') }}</button></form><small>{{ uiText('只可申请加入已开放申请的群组。邀请需要你确认后才会加入。') }}</small><h4>{{uiText('我发出的邀请与申请')}}</h4><p v-if="!history.length">{{uiText('暂无记录')}}</p><div v-for="entry in history" :key="entry.id" class="invite-row"><div><strong>{{entry.groupName}}</strong><small>{{entry.kind==='INVITE'?entry.displayName:uiText('申请加入')}} · {{entry.identityCode}}</small></div><span>{{statusText(entry.status)}}</span><button v-if="entry.status==='PENDING'" class="table-action" :disabled="busy" @click="run('/workspaces/invitations/'+entry.id+'/cancel',{})">{{uiText('撤回')}}</button></div><nav class="invite-row"><button class="table-action" :disabled="busy||!page" @click="historyPage(page-1)">{{uiText('上一页')}}</button><span>{{page+1}}</span><button class="table-action" :disabled="busy||!hasNext" @click="historyPage(page+1)">{{uiText('下一页')}}</button></nav></details></template>
<style scoped>.invitation-panel{padding:16px 0;border-bottom:1px solid var(--line);font-size:13px}summary{cursor:pointer;color:var(--green)}form,.invite-row{display:flex;align-items:center;gap:16px;padding:14px 0}label{display:flex;align-items:center;gap:12px}.invite-row strong{flex:1}small{color:var(--muted)}</style>
